/**
 * Type definitions for events.module.css
 * 
 * Provides type-safe access to CSS module class names for event-related styling.
 * These types are automatically generated from the CSS module and ensure
 * type safety when using the styles in TypeScript components.
 * 
 * @example
 * ```tsx
 * import styles from './events.module.css';
 * 
 * function EventComponent() {
 *   return <div className={styles.eventItem}>Event Content</div>;
 * }
 * ```
 */

declare const styles: {
  /**
   * Class name for event item containers
   * Applies hover effects and theme-aware styling
   */
  readonly eventItem: string;
};

export default styles;
